INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(24850, 5, 0, 'plPL', 'Kalegos doprowadza Sathrovarra do szaleńczej furii!'),
(25165, 0, 0, 'plPL', 'Niedola...'),
(25165, 1, 0, 'plPL', 'Dezorientacja...'),
(25165, 2, 0, 'plPL', 'Nieufność...'),
(25165, 3, 0, 'plPL', 'Oto znamiona...'),
(25166, 0, 0, 'plPL', 'Zepsucie...'),
(25166, 1, 0, 'plPL', 'Nienawiść...'),
(25166, 3, 0, 'plPL', 'Oto filary...'),
(37763, 5, 0, 'plPL', 'Odbierz miecz, $N, i zanieś go przez ten portal do Dalaranu. Vereesa Bieżywiatr będzie tam czekać, by ci pogratulować.');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(24423, 'plPL', '', 'Cień w sukurs ogniowi!', 0),
(24424, 'plPL', '', 'Sacrolash kieruje Rozbłysk cienia na $n.', 0),
(24426, 'plPL', '', 'Alythess kieruje Pożar na $n.', 0),
(24452, 'plPL', '', 'Alythess! Twój ogień płonie we mnie!', 0),
(24983, 'plPL', 'Sathrovarr doprowadza Kalegosa do szaleńczej furii!', '', 0),
(25050, 'plPL', '', 'Dawać tu chochliki!', 0),
(25200, 'plPL', 'Jednostka przechodzi w tryb oszczędzania energii.', '', 0),
(25201, 'plPL', 'Wykryto zagrożenie w pobliżu. Wyjście z trybu oszczędzania energii.', '', 0),
(25202, 'plPL', 'Wrogowie w zasięgu wzroku! Atakujcie, a ja spróbuję uruchomić Obrońcę!', 'Wrogowie w zasięgu wzroku! Atakujcie, a ja spróbuję uruchomić Obrońcę!', 0),
(25203, 'plPL', 'Wykryto obecność wroga.', '', 0),
(25206, 'plPL', 'Jednostka sprawna i atakuje cele.', '', 0),
(25220, 'plPL', 'Chodźcie, spróbujcie szczęścia!', '', 0),
(25221, 'plPL', '', 'Stójcie, przyjaciele! Zanim ten diabeł spotka swój los, można się od niego czegoś dowiedzieć!', 0),
(25222, 'plPL', 'Marna jaszczurko! Jedyna odpowiedź, jaką tu znajdziesz, to śmierć!', '', 0),
(25223, 'plPL', 'Ba! Twoja magia jest słaba!', '', 0),
(25226, 'plPL', '', 'Gdzie jest Anveena, demonie? Co się stało z Kalecem?', 0),
(25227, 'plPL', '', 'Powiesz mi, gdzie są!', 0),
(25228, 'plPL', '', 'Mów! Mam dość pytania!', 0),
(25229, 'plPL', '', 'Malygosie, mój panie... zrobiłam... co mogłam.', 0),
(25263, 'plPL', 'Jestem twoim dłużnikiem na zawsze. Kiedy zatriumfujemy nad Kil\'jaedenem, cały ten świat również będzie twoim dłużnikiem.', '', 0),
(25482, 'plPL', 'Intruzi! Nie wpuśćcie ich do Sanktuarium!', '', 0),
(25496, 'plPL', 'Aaagh! Już nigdy nie będę niewolnikiem Malygosa! Rzućcie mi wyzwanie, a zostaniecie zniszczeni!', '', 0),
(25497, 'plPL', 'Oczyszczę was!', '', 0),
(25498, 'plPL', 'Wasz ból dopiero się zaczął!', '', 0),
(25499, 'plPL', 'W imię Kil\'jaedena!', '', 0),
(25500, 'plPL', 'Ostrzegałem was!', '', 0),
(25502, 'plPL', 'Kil\'jaeden musi zostać zniszczony!', '', 0),
(25513, 'plPL', '', 'Ogień w sukurs cieniowi!', 0),
(25514, 'plPL', '', 'Płomienie pochłaniają.', 0),
(25515, 'plPL', '', 'Edir harach!', 0),
(25516, 'plPL', '', 'Sacrolash!', 0),
(25517, 'plPL', '', 'Szczęście właśnie cię opuściło!', 0),
(25518, 'plPL', '', 'Der\'ek... manul.', 0),
(25519, 'plPL', '', 'Cienie pochłaniają.', 0),
(25520, 'plPL', '', 'Ee-nok Kryul!', 0),
(25521, 'plPL', '', 'Czas to luksus, na który już cię nie stać!', 0),
(25522, 'plPL', '', 'Ja... gasnę.', 0),
(25523, 'plPL', '', 'Cieszę się, że tu jesteś, $N. Sytuacja militarna na Płaskowyżu Słonecznej Studni jest dość ponura.', 0),
(25524, 'plPL', 'Złóż mi raport o sytuacji, kapitanie.', 'Złóż mi raport o sytuacji, kapitanie.', 0),
(25525, 'plPL', '', 'Ofensywa Straceńczego Słońca poczyniła wielkie postępy na obrzeżach Wyspy Quel\'Danas. Siły Kil\'jaedena są spychane, a w tym chaosie udało mi się poprowadzić tutaj, na Płaskowyż Słonecznej Studni, niewielki oddział zwiadowczy. Moi żołnierze przeszli przez Plac Parhelium, dostrzegli grupę krwawych elfów ze Słonecznego Ostrza i wtedy starliśmy się z wrogiem. Ta walka szybko zamieniła się w katastrofę.', 0),
(25526, 'plPL', 'Co poszło nie tak?', 'Co poszło nie tak?', 0),
(25527, 'plPL', '', 'Obrońcy Kil\'jaedena tutaj, na Płaskowyżu Słonecznej Studni, są znacznie silniejsi od wszystkiego, z czym mierzyliśmy się na zewnątrz, na wyspie. Legion wypaczył nawet naszą technologię Tajemnych strażników energią spaczenia, tworząc coś znacznie groźniejszego. Jeden jedyny Obrońca Słonecznego Ostrza zdziesiątkował moich żołnierzy, więc rozkazałam szybki odwrót. Spodziewałam się, że mój oddział zostanie całkiem zepchnięty z płaskowyżu, ale wróg zaskoczył mnie i przerwał pościg.', 0),
(25528, 'plPL', 'Dlaczego przestali?', 'Dlaczego przestali?', 0),
(25529, 'plPL', '', 'Nie wiem, ale cieszę się, że tak się stało. Dzięki tej chwili wytchnienia Anachoreta Elbadon zdołał ocalić wielu podległych mi mężczyzn i kobiet. Wysłałam naprzód kilku moich najbardziej skrytych zwiadowców i przynieśli ciekawe wieści. Niemal wszyscy Obrońcy Słonecznego Ostrza są wyłączeni! Wygląda na to, że siły Kil\'jaedena oszczędzają energię i zadowalają się powstrzymywaniem nas jednym aktywnym Obrońcą. Jeśli ty i twoi towarzysze chcecie wedrzeć się do środka, pozwól, że zaproponuję plan ataku.', 0),
(25530, 'plPL', 'Dziękuję za twoje spostrzeżenia.', 'Dziękuję za twoje spostrzeżenia.', 0),
(25531, 'plPL', '', 'Wykorzystajcie to, że ich Obrońcy Słonecznego Ostrza są wyłączeni. Jeśli dostrzeże was któryś z ich zwiadowców Słonecznego Ostrza, ten elf na pewno spróbuje ponownie uruchomić pobliskiego Obrońcę. Zabijcie go szybko, żeby temu zapobiec. Gdy krwawe elfy zostaną wyeliminowane, a wy nie uruchomicie czujników zbliżeniowych Obrońcy, powinniście przejść obok bez walki. Oszczędzicie w ten sposób i czas, i siły.', 0),
(25532, 'plPL', 'Kapitan Selana poleciła mi wspierać wasze wysiłki tutaj, na Płaskowyżu Słonecznej Studni.', '', 0),
(25533, 'plPL', 'Jaki jest obecny stan bram Słonecznej Studni?', 'Jaki jest obecny stan bram Słonecznej Studni?', 0),
(25534, 'plPL', 'Agamath, Pierwsza Brama, została przełamana. Dwie z najpotężniejszych poruczniczek Kil\'jaedena, Lady Sacrolash i Wielka Czarnoksiężniczka Alythess, są teraz podatne na atak.', '', 0),
(25535, 'plPL', 'Wszystkie trzy bariery działają w pełni. Porozmawiaj z arcymagiem Ne\'thulem w Porcie Słonecznego Zasięgu, żeby pomóc w otwarciu bram.', '', 0),
(25536, 'plPL', 'Agamath, Pierwsza Brama, i Rohendor, Druga Brama, zostały zniszczone. Pozostał tylko Archonisus, Trzecia Brama.', '', 0),
(25537, 'plPL', 'Wszystkie bariery blokujące wam drogę do Słonecznej Studni zostały zniszczone. Wejdźcie do Słonecznej Studni i powstrzymajcie Kil\'jaedena przed wkroczeniem do tego świata!', '', 0),
(25538, 'plPL', 'Teraz, gdy Kalegos jest wolny, czy możesz mnie teleportować do Punktu Szczytowego?', 'Teraz, gdy Kalegos jest wolny, czy możesz mnie teleportować do Punktu Szczytowego?', 0),
(25539, 'plPL', 'Lady Sacrolash i Wielka Czarnoksiężniczka Alythess zostały pokonane. Czy możesz mnie teleportować do Sanktuarium Wiedźmy?', 'Lady Sacrolash i Wielka Czarnoksiężniczka Alythess zostały pokonane. Czy możesz mnie teleportować do Sanktuarium Wiedźmy?', 0),
(25540, 'plPL', 'Utorowaliśmy drogę do Kil\'jaedena! Czy możesz mnie przenieść w pobliże Słonecznej Studni?', 'Utorowaliśmy drogę do Kil\'jaedena! Czy możesz mnie przenieść w pobliże Słonecznej Studni?', 0),
(25544, 'plPL', 'Wszystkie moje plany prowadziły do tej chwili!', '', 0),
(25545, 'plPL', 'Trzymajcie się zadania, nie traćcie czasu!', '', 0),
(25546, 'plPL', 'Dość się naczekałem!', '', 0),
(25547, 'plPL', 'Zawiedźcie mnie, a będziecie cierpieć przez wieczność!', '', 0),
(25548, 'plPL', 'Wyssijcie dziewczynę! Wysysajcie jej moc, aż zostanie z niej pusta skorupa!', '', 0),
(25628, 'plPL', 'Ach, kolejne owieczki na rzeź!', '', 0),
(25629, 'plPL', 'Giń, insekcie!', '', 0),
(25630, 'plPL', 'Jesteś mięsem!', '', 0),
(25631, 'plPL', 'Zbyt łatwe!', '', 0),
(25632, 'plPL', 'Chodźcie tu i walczcie!', '', 0),
(25633, 'plPL', 'Kolejny dzień, kolejna chwalebna bitwa!', '', 0),
(25634, 'plPL', 'Dla tego żyję!', '', 0),
(25635, 'plPL', 'Tyle z prawdziwego wyzwania. Giń!', '', 0),
(25636, 'plPL', 'Aaagh! Brawo! Teraz robi się... ciekawie...', '', 0),
(37441, 'plPL', 'Czy to naprawdę może być Quel\'Delar?', '', 0),
(37442, 'plPL', 'Zobaczymy.', '', 0),
(37444, 'plPL', 'Spójrz na niego, Lor\'themarze. To z pewnością Quel\'Delar.', '', 0),
(37449, 'plPL', 'To rzeczywiście Quel\'Delar. Nie sądziłem, że dożyję dnia, w którym legendarny miecz Thaloriena Szukającego Świtu zostanie nam zwrócony.', '', 0),
(37450, 'plPL', 'Jesteś $gbohaterem:bohaterką; i natchnieniem dla sin\'dorei, $n, symbolem naszej wytrwałości w obliczu tragedii i zdrady.', '', 0),
(37451, 'plPL', 'Regent mówi prawdę, $n. Poświęcenie Thaloriena nie zdołało zapobiec upadkowi tej właśnie Słonecznej Studni.', '', 0),
(37452, 'plPL', 'Kiedy $gznalazłeś:znalazłaś; ten miecz, był złamany i porzucony, tak jak Srebrna Luna po zdradzie Kael\'thasa.', '', 0),
(37453, 'plPL', 'Niech Quel\'Delar będzie znakiem, że nigdy się nie poddamy, że stawimy czoła każdemu wrogowi bez strachu.', '', 0),
(37454, 'plPL', 'Nie tylko sin\'dorei darzą Quel\'Delar wielkim szacunkiem. Ma on miejsce w sercach wszystkich dzieci Srebrnej Luny.', '', 0),
(37455, 'plPL', 'To ostrze zostało nam zwrócone nie bez powodu, panowie. Nadszedł czas, by zjednoczyć się za posiadaczem Quel\'Delara i pomścić zniszczenie Srebrnej Luny i Słonecznej Studni.', '', 0),
(37456, 'plPL', 'Odbierz miecz, $n, i zanieś go przez ten portal do Dalaranu. Arcymag Aethas Słońcobójca będzie tam czekać, by ci pogratulować.', '', 0),
(37820, 'plPL', 'Panie i panowie, przedstawiam $gposiadacza:posiadaczkę; Quel\'Delara: $n.', '', 0),
(44549, 'plPL', 'Chaos...', '', 0),
(46444, 'plPL', 'To było zabawne.', '', 0);
